package com.fuwaki.djifly.probe

import com.google.gson.*
import org.junit.Assert.*
import org.junit.Test

/** Values are imported from backend commit a11d931, not generated by the tested Kotlin code. */
open class BackendA11d931GoldenTest {
    protected open val fixtureRoot = "/backend-a11d931"
    private val p = PinnedDraftProbe
    private fun resource(name: String) = javaClass.getResourceAsStream("$fixtureRoot/$name")!!.use { it.readBytes() }
    private val golden by lazy { JsonParser.parseString(resource("golden-vectors.json").toString(Charsets.UTF_8)).asJsonObject }
    private val vectors get() = golden["vectors"].asJsonArray.map { it.asJsonObject }
    private fun input(index: Int = 0) = p.rawHex(vectors[index]["inputUtf8Hex"].asString)
    private fun base() = p.envelope(input())
    private fun rejected(layer: String, block: () -> Unit) {
        try { block(); fail("Expected $layer rejection") } catch (e: DraftProbeRejected) { assertEquals(layer, e.layer) }
    }
    private fun encoded(e: JsonElement) = e.toString().toByteArray(Charsets.UTF_8)

    protected open val fingerprints = mapOf(
        "DRAFT.md" to "999020874207ead51692e29133c2d9fa6d24b75abdd53e2e8ce6aa8a82ff35cc",
        "golden-vectors.json" to "08228ecea348d292db2cdf688112b0d2aae8ade3f1ac6daaaccf4e29e1b2a9b4",
        "verify-golden.mjs" to "e499d44c91567600ac1b844532abbd01443b180a06aedf4372e96548b663d8fa"
    )
    @Test fun importedSnapshotsHavePinnedProvenanceFingerprints() {
        fingerprints.forEach { (file, sha) -> assertEquals(file, sha, p.sha(resource(file))) }
    }

    @Test fun allFourPacketsMatchCanonicalBytesIdentityAnchorsChainAndContentDigests() {
        assertEquals(4, vectors.size)
        assertEquals(p.identityFields, golden["identityFields"].asJsonArray.map { it.asString })
        vectors.forEach { v ->
            val raw = p.rawHex(v["inputUtf8Hex"].asString)
            val packet = p.envelope(raw)
            assertArrayEquals(v["name"].asString, p.rawHex(v["canonicalUtf8Hex"].asString), p.canonical(packet))
            assertArrayEquals(p.rawHex(v["withoutChainHashHex"].asString), p.canonical(p.withoutHash(packet)))
            assertEquals(v["anchorHex"].asString, p.anchor(packet))
            assertEquals(v["chainHashHex"].asString, p.chain(packet))
            assertEquals(v["contentDigestHex"].asString, p.sha(p.canonical(packet)))
            assertEquals(v["rawSha256Hex"].asString, p.sha(raw))
            p.selfHash(packet)
        }
        assertArrayEquals(golden["identityCanonicalUtf8"].asString.toByteArray(), p.canonical(p.identity(base())))
        assertEquals(golden["anchorHex"].asString, p.anchor(base()))
    }
    @Test fun lineSeparatorsEAcuteAndSlashMatchExactCanonicalUtf8() {
        val fixtures = golden["canonicalFixtures"].asJsonArray
        assertEquals(1, fixtures.size())
        fixtures.forEach { f ->
            val fixture = f.asJsonObject
            val actual = p.canonical(p.strict(p.rawHex(fixture["inputUtf8Hex"].asString)))
            assertArrayEquals(p.rawHex(fixture["canonicalUtf8Hex"].asString), actual)
            assertEquals("{\"s\":\"é/\u2028\u2029\",\"z\":1}", actual.toString(Charsets.UTF_8))
            assertFalse(actual.toString(Charsets.UTF_8).contains("\\u2028"))
        }
    }
    @Test fun canonicalReplayIsNotLocalOriginalByteFingerprint() {
        assertArrayEquals(p.canonical(p.envelope(input(0))), p.canonical(p.envelope(input(1))))
        assertNotEquals(p.sha(input(0)), p.sha(input(1)))
        assertEquals(vectors[0]["contentDigestHex"], vectors[1]["contentDigestHex"])
    }
    @Test fun heightTwoAndOtherAirframeHaveCorrectDistinctLinkage() {
        val first = p.envelope(input(0)); val next = p.envelope(input(2)); val other = p.envelope(input(3))
        assertEquals(first["packetId"], next["prevPacketId"])
        assertEquals(first["chainHash"], next["prevChainHash"])
        assertNotEquals(p.anchor(first), p.anchor(other))
        assertNotEquals(first["serialSource"], other["serialSource"])
    }
    @Test fun malformedUtf8SurrogatesAndBomAreStrictJsonFailures() {
        listOf(byteArrayOf(0xc3.toByte(),0x28), byteArrayOf(0xed.toByte(),0xa0.toByte(),0x80.toByte())).forEach {
            rejected("STRICT_JSON") { p.strict("{\"s\":\"".toByteArray() + it + "\"}".toByteArray()) }
        }
        rejected("STRICT_JSON") { p.strict(byteArrayOf(0xef.toByte(),0xbb.toByte(),0xbf.toByte()) + input()) }
        listOf("{\"s\":\"\\ud800\"}", "{\"\\udc00\":1}").forEach { s -> rejected("STRICT_JSON") { p.strict(s.toByteArray()) } }
        p.strict("{\"s\":\"\\ud83d\\ude00\"}".toByteArray())
    }
    @Test fun unicodeEscapeHexMustBeAsciiBeforeCanonicalization() {
        listOf("\\uＦＦＦＦ", "\\u０000", "\\u066٠").forEach { escaped ->
            rejected("STRICT_JSON") { p.strict("{\"s\":\"$escaped\"}".toByteArray()) }
        }
        assertEquals("{\"s\":\"é\"}", p.canonical(p.strict("{\"s\":\"\\u00E9\"}".toByteArray())).toString(Charsets.UTF_8))
    }
    @Test fun hashAndUuidRejectNonAsciiOrUppercaseHexAtSchemaLayer() {
        listOf("a".repeat(63) + "ａ", "a".repeat(63) + "١", "A".repeat(64)).forEach { hash ->
            val q = base(); q.addProperty("chainHash", hash)
            rejected("SCHEMA") { p.envelope(encoded(q)) }
        }
        val q = base(); q.addProperty("packetId", "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaＦ")
        rejected("SCHEMA") { p.envelope(encoded(q)) }
    }
    @Test fun duplicateNullEscapedNamesAndLeadingZeroAreStrictJsonFailures() {
        listOf("{\"a\":null,\"a\":1}", "{\"a\":null,\"\\u0061\":1}", "{\"a\":[{\"b\":null,\"b\":2}]}", "{\"a\":01}").forEach {
            rejected("STRICT_JSON") { p.strict(it.toByteArray()) }
        }
    }
    @Test fun draftIntegerTokenProfileIsStricterThanJcsItself() {
        listOf("-0", "-0.0", "1.0", "1e3", "1E0", "NaN", "Infinity", "1e309", "9007199254740992", "9007199254740993", "-9007199254740992").forEach {
            rejected("STRICT_JSON") { p.strict("{\"n\":$it}".toByteArray()) }
        }
        listOf("9007199254740991", "-9007199254740991", "0").forEach {
            assertEquals("{\"n\":$it}", p.canonical(p.strict("{\"n\":$it}".toByteArray())).toString(Charsets.UTF_8))
        }
    }
    @Test fun requiredMissingNullAndUnknownRootHaveDifferentSchemaMeaning() {
        val missing = base(); missing.remove("prevPacketId")
        rejected("SCHEMA") { p.envelope(encoded(missing)) }
        assertTrue(base()["prevPacketId"].isJsonNull)
        val later = p.envelope(input(2)); later.add("prevPacketId", JsonNull.INSTANCE)
        rejected("SCHEMA") { p.envelope(encoded(later)) }
        val nullAssignment = base(); nullAssignment.add("assignmentVersion", JsonNull.INSTANCE)
        rejected("SCHEMA") { p.envelope(encoded(nullAssignment)) }
        val zeroAssignment = base(); zeroAssignment.addProperty("assignmentVersion", 0)
        rejected("SCHEMA") { p.envelope(encoded(zeroAssignment)) }
        val unknown = base(); unknown.addProperty("displayName", "not a stable key")
        rejected("SCHEMA") { p.envelope(encoded(unknown)) }
        assertNotEquals(p.sha(p.canonical(p.strict("{}".toByteArray()))), p.sha(p.canonical(p.strict("{\"a\":null}".toByteArray()))))
    }
    @Test fun identityRepeatedFieldsAndPathMustMatchKnownChainBeforeUsingIt() {
        val expected = p.identity(base())
        p.identityFields.forEach { field ->
            val q = base()
            when (field) {
                "schemaVersion", "hashVersion", "assignmentVersion" -> q.addProperty(field, 2)
                "chainId", "recordingSourceId", "orderId" -> q.addProperty(field, "cccccccc-cccc-4ccc-8ccc-cccccccccccc")
                "serialSource" -> q.addProperty(field, "PRODUCT")
                else -> q.addProperty(field, q[field].asString + "x")
            }
            if (field in listOf("schemaVersion", "hashVersion")) {
                rejected("SCHEMA") { p.envelope(encoded(q)) }
            } else {
                val structurallyValid = p.envelope(encoded(q))
                rejected(if (field == "orderId") "SCHEMA" else "BINDING") { p.binding(structurallyValid, base()["orderId"].asString, expected) }
            }
        }
        rejected("SCHEMA") { p.binding(base(), "different-path-order", expected) }
        p.binding(base(), base()["orderId"].asString, expected)
    }
    @Test fun arrayOrderIsPreservedAndChangedEventOrderBreaksOriginalSelfHash() {
        val q = base(); val events = q["events"].asJsonArray
        val second = events[0].deepCopy().asJsonObject
        second.addProperty("eventId", "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb")
        events.add(second)
        val reversed = q.deepCopy(); reversed.add("events", JsonArray().also { it.add(events[1]); it.add(events[0]) })
        assertNotEquals(p.sha(p.canonical(p.withoutHash(q))), p.sha(p.canonical(p.withoutHash(reversed))))
        rejected("SELF_HASH") { p.selfHash(q) }
        rejected("SELF_HASH") { p.selfHash(reversed) }
        assertEquals("[2,1]", p.canonical(p.strict("[2,1]".toByteArray())).toString(Charsets.UTF_8))
    }
    @Test fun duplicateEventIdsAreWholePacketSchemaButEventSemanticsRemainServerOwned() {
        val dup = base(); dup["events"].asJsonArray.add(dup["events"].asJsonArray[0].deepCopy())
        rejected("SCHEMA") { p.envelope(encoded(dup)) }
        val empty = base(); empty.add("events", JsonArray())
        rejected("SCHEMA") { p.envelope(encoded(empty)) }
        val unknownType = base(); unknownType["events"].asJsonArray[0].asJsonObject.addProperty("type", "UNKNOWN")
        p.envelope(encoded(unknownType)) // UNKNOWN_EVENT_TYPE is per-event, not strict parser failure.
        val outOfRange = base()
        outOfRange["events"].asJsonArray[0].asJsonObject["payload"].asJsonObject.addProperty("latitudeDegE7", 900000001)
        p.envelope(encoded(outOfRange)) // Range/time/auth verdicts are not faked by this offline probe.
    }
    @Test fun eventTimeSafeIntegerIsTransportNotTimeWindowAcceptance() {
        listOf(0L, 9007199254740991L).forEach { time ->
            val q = base(); q["events"].asJsonArray[0].asJsonObject.addProperty("capturedAt", time)
            p.envelope(encoded(q)) // Does NOT mean within the assignment/server time window.
        }
        val negativeTime = base(); negativeTime["events"].asJsonArray[0].asJsonObject.addProperty("capturedAt", -1L)
        rejected("SCHEMA") { p.envelope(encoded(negativeTime)) }
        val textTime = base(); textTime["events"].asJsonArray[0].asJsonObject.addProperty("capturedAt", "1710000000000")
        rejected("SCHEMA") { p.envelope(encoded(textTime)) }
        val missingTime = base(); missingTime["events"].asJsonArray[0].asJsonObject.remove("capturedAt")
        rejected("SCHEMA") { p.envelope(encoded(missingTime)) }
    }

    @Test fun decomposedUnicodeIsNotSilentlyNormalized() {
        val a = p.canonical(p.strict("{\"s\":\"é\"}".toByteArray()))
        val b = p.canonical(p.strict("{\"s\":\"e\\u0301\"}".toByteArray()))
        assertNotEquals(p.sha(a), p.sha(b))
    }
}
